8	/// A feedback entry.
9	#[derive(Debug, Clone, Serialize, Deserialize)]
10	pub struct FeedbackEntry {
11	    /// Unique feedback ID.
12	    pub id: String,
13	    /// Timestamp when feedback was created.
14	    pub timestamp: Option<DateTime<Utc>>,
15	    /// The feedback message.
16	    pub message: String,
17	    /// Tags for categorization.
18	    #[serde(default)]
19	    pub tags: Vec<String>,
20	    /// Associated session ID.
21	    #[serde(skip_serializing_if = "Option::is_none")]
22	    pub session_id: Option<SessionId>,
23	    /// Feedback status.
24	    #[serde(default)]
25	    pub status: FeedbackStatus,
26	    /// Resolution note (if resolved).
27	    #[serde(skip_serializing_if = "Option::is_none")]
28	    pub resolution: Option<String>,
29	    /// Resolution timestamp.
30	    #[serde(skip_serializing_if = "Option::is_none")]
31	    pub resolved_at: Option<DateTime<Utc>>,
32	    /// Whether this entry was delivered externally.
33	    #[serde(skip_serializing_if = "Option::is_none")]
34	    pub delivered: Option<bool>,
35	}
