37	/// Feedback status.
38	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
39	#[serde(rename_all = "lowercase")]
40	pub enum FeedbackStatus {
41	    /// Feedback is open and needs attention.
42	    #[default]
43	    Open,
44	    /// Feedback is being worked on.
45	    InProgress,
46	    /// Feedback has been resolved.
47	    Resolved,
48	    /// Feedback won't be addressed.
49	    WontFix,
50	}
51	
52	impl FeedbackEntry {
53	    /// Create a new feedback entry.
54	    pub fn new(message: impl Into<String>) -> Self {
55	        let mut id_bytes = [0u8; 6];
56	        crate::sys::random_bytes(&mut id_bytes);
57	
58	        Self {
59	            id: format!("fb_{}", hex::encode(id_bytes)),
60	            timestamp: Some(Utc::now()),
61	            message: message.into(),
62	            tags: Vec::new(),
63	            session_id: None,
64	            status: FeedbackStatus::Open,
65	            resolution: None,
66	            resolved_at: None,
67	            delivered: None,
68	        }
69	    }
70	
71	    /// Attach a session ID.
72	    pub fn with_session(mut self, session_id: SessionId) -> Self {
73	        self.session_id = Some(session_id);
74	        self
75	    }
76	
77	    /// Add tags.
78	    pub fn with_tags(mut self, tags: Vec<impl Into<String>>) -> Self {
79	        self.tags = tags.into_iter().map(Into::into).collect();
80	        self
81	    }
82	
83	    /// Mark as resolved.
84	    pub fn resolve(&mut self, resolution: impl Into<String>) {
85	        self.status = FeedbackStatus::Resolved;
86	        self.resolution = Some(resolution.into());
87	        self.resolved_at = Some(Utc::now());
88	    }
89	
90	    /// Mark as won't fix.
91	    pub fn wont_fix(&mut self, reason: impl Into<String>) {
92	        self.status = FeedbackStatus::WontFix;
93	        self.resolution = Some(reason.into());
94	        self.resolved_at = Some(Utc::now());
95	    }
96	
97	    /// Mark as in progress.
98	    pub fn start_progress(&mut self) {
99	        self.status = FeedbackStatus::InProgress;
100	    }
101	}
