1	//! Session metadata capture.
2	
3	use chrono::{DateTime, Utc};
4	use serde::{Deserialize, Serialize};
5	use std::collections::HashMap;
6	use std::time::Duration;
7	
8	/// Metadata for a session.
9	#[derive(Debug, Clone, Serialize, Deserialize)]
10	pub struct SessionMetadata {
11	    /// Command that was run (e.g., "run", "list", "status").
12	    pub command: String,
13	    /// Command arguments.
14	    pub args: Vec<String>,
15	    /// Flags that were set.
16	    pub flags: HashMap<String, serde_json::Value>,
17	    /// Current working directory.
18	    pub cwd: Option<String>,
19	    /// Config file path used.
20	    pub config_path: Option<String>,
21	    /// Hash of config at time of session.
22	    pub config_hash: Option<String>,
23	    /// Session start time.
24	    pub start_time: Option<DateTime<Utc>>,
25	    /// Session end time.
26	    pub end_time: Option<DateTime<Utc>>,
27	    /// Exit code.
28	    pub exit_code: Option<i32>,
29	    /// Captured stdout.
30	    pub stdout: String,
31	    /// Captured stderr.
32	    pub stderr: String,
33	    /// Command-specific context.
34	    #[serde(default)]
35	    pub context: SessionContext,
36	}
37	
38	/// Command-specific context data.
39	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
40	pub struct SessionContext {
41	    /// For run: step results.
42	    #[serde(skip_serializing_if = "Vec::is_empty", default)]
43	    pub step_results: Vec<StepResultSummary>,
44	    /// For run: workflow name.
45	    #[serde(skip_serializing_if = "Option::is_none")]
46	    pub workflow: Option<String>,
47	    /// For status/list: steps shown.
48	    #[serde(skip_serializing_if = "Vec::is_empty", default)]
49	    pub steps_shown: Vec<String>,
50	    /// For init: files created.
51	    #[serde(skip_serializing_if = "Vec::is_empty", default)]
52	    pub files_created: Vec<String>,
53	    /// Any errors that occurred.
54	    #[serde(skip_serializing_if = "Vec::is_empty", default)]
55	    pub errors: Vec<String>,
56	}
57	
58	/// Summary of a step result.
59	#[derive(Debug, Clone, Serialize, Deserialize)]
60	pub struct StepResultSummary {
61	    /// Step name.
62	    pub name: String,
63	    /// Step status (success, failed, skipped).
64	    pub status: String,
65	    /// Duration in milliseconds.
66	    pub duration_ms: Option<u64>,
67	    /// Error message if failed.
68	    pub error: Option<String>,
69	}
70	
71	impl SessionMetadata {
72	    /// Create new session metadata.
73	    pub fn new(command: impl Into<String>, args: Vec<String>) -> Self {
74	        Self {
75	            command: command.into(),
76	            args,
77	            flags: HashMap::new(),
78	            cwd: std::env::current_dir()
79	                .ok()
80	                .map(|p| p.display().to_string()),
81	            config_path: None,
82	            config_hash: None,
83	            start_time: Some(Utc::now()),
84	            end_time: None,
85	            exit_code: None,
86	            stdout: String::new(),
87	            stderr: String::new(),
88	            context: SessionContext::default(),
89	        }
90	    }
91	
92	    /// Set a flag value.
93	    pub fn set_flag(&mut self, key: impl Into<String>, value: impl Into<serde_json::Value>) {
94	        self.flags.insert(key.into(), value.into());
95	    }
96	
97	    /// Set config info.
98	    pub fn set_config(&mut self, path: impl Into<String>, hash: impl Into<String>) {
99	        self.config_path = Some(path.into());
100	        self.config_hash = Some(hash.into());
101	    }
102	
103	    /// Finalize the session with results.
104	    pub fn finalize(&mut self, exit_code: i32, stdout: String, stderr: String) {
105	        self.end_time = Some(Utc::now());
106	        self.exit_code = Some(exit_code);
107	        self.stdout = stdout;
108	        self.stderr = stderr;
109	    }
110	
111	    /// Get session duration.
112	    pub fn duration(&self) -> Option<Duration> {
113	        match (self.start_time, self.end_time) {
114	            (Some(start), Some(end)) => {
115	                let diff = end.signed_duration_since(start);
116	                Some(Duration::from_millis(diff.num_milliseconds() as u64))
117	            }
118	            _ => None,
119	        }
120	    }
121	
122	    /// Add a step result summary.
123	    pub fn add_step_result(&mut self, result: StepResultSummary) {
124	        self.context.step_results.push(result);
125	    }
126	
127	    /// Add an error message.
128	    pub fn add_error(&mut self, error: impl Into<String>) {
129	        self.context.errors.push(error.into());
130	    }
131	}
