398	/// Get the flag to pass commands to the shell.
399	///
400	/// Uses `-c` (non-login, non-interactive) on Unix. Bivvy inherits
401	/// the invoking shell's environment, so re-sourcing login configs
402	/// via `-l` is unnecessary and can override the correct PATH/tool
403	/// versions that are already set up in the parent environment.
404	///
405	/// **Why not `-l` (login)?**  The parent shell has already sourced
406	/// `.zprofile`/`.bash_profile`/`.zshenv`. Re-sourcing them in the
407	/// child can reset PATH modifications made by version managers
408	/// (mise, asdf, rbenv) that activate per-directory, causing the
409	/// wrong tool version to be used.
410	///
411	/// **Why not `-i` (interactive)?**  The `-i` flag makes the child
412	/// shell set up job control: it calls `setpgid`/`tcsetpgrp` to create
413	/// its own process group and steal the terminal foreground. This causes:
414	///   - **SIGTTOU** — bivvy becomes a background process; terminal
415	///     writes trigger "zsh: suspended (tty output)"
416	///   - **Ctrl+C/Ctrl+Z broken** — signals go to the child's process
417	///     group, not bivvy's, so the user can't interrupt or suspend
418	///   - **Prompt hangs** — after the child exits, bivvy is background;
419	///     `read_key()` returns EIO or blocks
420	fn shell_flag(_shell: &str) -> &'static str {
421	    if cfg!(target_os = "windows") {
422	        "/C"
423	    } else {
424	        "-c"
425	    }
426	}
