1	//! Shell refresh detection.
2	//!
3	//! This module provides functionality for detecting when PATH changes
4	//! require a shell refresh.
5	
6	use std::collections::HashSet;
7	
8	/// Tracks PATH changes that require shell refresh.
9	///
10	/// # Example
11	///
12	/// ```
13	/// use bivvy::shell::PathChangeDetector;
14	///
15	/// let mut detector = PathChangeDetector::new();
16	/// detector.expect_additions(vec!["/nonexistent/path"]);
17	///
18	/// let result = detector.check();
19	/// assert!(result.needs_refresh);
20	/// assert!(!result.missing_paths.is_empty());
21	/// ```
22	pub struct PathChangeDetector {
23	    /// PATH value at start of execution.
24	    initial_path: String,
25	    /// Expected path additions from steps.
26	    expected_additions: HashSet<String>,
27	}
28	
29	/// Result of checking for PATH changes.
30	#[derive(Debug)]
31	pub struct PathChangeResult {
32	    /// Whether a shell refresh is needed.
33	    pub needs_refresh: bool,
34	    /// Paths that were expected but not found in current PATH.
35	    pub missing_paths: Vec<String>,
36	    /// Human-readable message explaining the change.
37	    pub message: Option<String>,
38	}
39	
40	impl PathChangeDetector {
41	    /// Create a detector capturing the current PATH.
42	    pub fn new() -> Self {
43	        Self {
44	            initial_path: std::env::var("PATH").unwrap_or_default(),
45	            expected_additions: HashSet::new(),
46	        }
47	    }
48	
49	    /// Record that a step is expected to add paths.
50	    pub fn expect_additions(&mut self, paths: impl IntoIterator<Item = impl Into<String>>) {
51	        for path in paths {
52	            self.expected_additions.insert(path.into());
53	        }
54	    }
55	
56	    /// Check if expected path additions are present.
57	    pub fn check(&self) -> PathChangeResult {
58	        let current_path = std::env::var("PATH").unwrap_or_default();
59	        let separator = if cfg!(windows) { ';' } else { ':' };
60	        let current_parts: HashSet<&str> = current_path.split(separator).collect();
61	
62	        let missing: Vec<String> = self
63	            .expected_additions
64	            .iter()
65	            .filter(|p| !current_parts.contains(p.as_str()))
66	            .cloned()
67	            .collect();
68	
69	        let needs_refresh = !missing.is_empty();
70	        let message = if needs_refresh {
71	            Some(format!(
72	                "Shell refresh needed to add {} path(s) to PATH",
73	                missing.len()
74	            ))
75	        } else {
76	            None
77	        };
78	
79	        PathChangeResult {
80	            needs_refresh,
81	            missing_paths: missing,
82	            message,
83	        }
84	    }
85	
86	    /// Get the initial PATH value.
87	    pub fn initial_path(&self) -> &str {
88	        &self.initial_path
89	    }
90	
91	    /// Get the number of expected additions.
92	    pub fn expected_count(&self) -> usize {
93	        self.expected_additions.len()
94	    }
95	}
96	
97	impl Default for PathChangeDetector {
98	    fn default() -> Self {
99	        Self::new()
100	    }

