    #[test]
    fn registry_resolves_from_remote_http() {
        let server = MockServer::start();

        let template_yaml = r#"
name: remote-tool
description: "Remote tool template"
category: tools
step:
  command: remote-tool run
"#;

        server.mock(|when, then| {
