150	/// Check whether a background update process is already running (or ran recently).
151	///
152	/// Uses a lock file with a timestamp. If the lock is less than 5 minutes old,
153	/// we assume the process is still active or just finished.
154	fn is_update_process_running() -> bool {
155	    let path = match lock_path() {
156	        Some(p) => p,
157	        None => return false,
158	    };
159	
160	    if let Ok(meta) = fs::metadata(&path) {
161	        if let Ok(modified) = meta.modified() {
162	            if let Ok(age) = modified.elapsed() {
163	                return age.as_secs() < 300;
164	            }
165	        }
166	    }
167	
168	    false
169	}
170	
171	/// Write a lock file to prevent concurrent background update processes.
172	fn write_lock_file() -> Result<()> {
173	    let path = lock_path().context("No cache directory for lock file")?;
174	    if let Some(parent) = path.parent() {
175	        fs::create_dir_all(parent)?;
176	    }
177	    fs::write(&path, Utc::now().to_rfc3339())?;
178	    Ok(())
179	}
180	
181	/// Remove the lock file after the background process completes.
182	fn remove_lock_file() {
183	    if let Some(path) = lock_path() {
184	        let _ = fs::remove_file(path);
185	    }
186	}
