612	
613	/// Load and merge configs with trust verification for remote extends URLs.
614	///
615	/// This is the full-featured config loader that verifies trust for remote
616	/// extends URLs. The `trust_policy` determines behavior for untrusted URLs:
617	/// - `TrustAll`: auto-trusts (--trust flag)
618	/// - `Prompt`: asks the user via UI (interactive mode)
619	/// - `Reject`: errors on untrusted URLs (non-interactive mode)
620	///
621	/// Trusted URLs are persisted so they don't need to be re-approved.
622	pub fn load_merged_config_with_trust(
623	    project_root: &Path,
624	    resolver: &ExtendsResolver,
625	    trust_policy: TrustPolicy,
626	    trust_store_path: &Path,
627	    ui: &mut dyn Prompter,
628	) -> Result<BivvyConfig> {
629	    let paths = ConfigPaths::discover(project_root);
630	
631	    if !paths.has_project_config() {
632	        return Err(BivvyError::ConfigNotFound {
633	            path: project_root.join(".bivvy").join("config.yml"),
634	        });
635	    }
636	
637	    let configs = collect_config_values(&paths, WorkflowSelection::All)?;
638	
639	    let merged = merge_configs(&configs);
640	
641	    let mut config: BivvyConfig =
642	        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
643	            path: project_root.join(".bivvy").join("config.yml"),
644	            message: format!("Failed to parse merged config: {}", e),
645	        })?;
646	
647	    // Migrate deprecated fields (watches → change checks, etc.)
648	    config.migrate_deprecated_fields();
649	
650	    if config.extends.is_some() {
651	        let mut trust_store = TrustStore::load(trust_store_path).map_err(BivvyError::Other)?;
652	        let mut store_modified = false;
653	
654	        let resolved = resolver
655	            .resolve_with_trust(&config, &mut |url: &str| {
656	                if trust_store.is_trusted(url) {
657	                    return Ok(());
658	                }
659	
660	                match trust_policy {
661	                    TrustPolicy::TrustAll => {
662	                        trust_store.trust(url);
663	                        store_modified = true;
664	                        Ok(())
665	                    }
666	                    TrustPolicy::Reject => Err(anyhow::anyhow!(
667	                        "Untrusted remote config URL: {}. Use --trust to auto-approve or run interactively to confirm.",
668	                        url
669	                    )),
670	                    TrustPolicy::Prompt => {
671	                        let prompt = Prompt {
672	                            key: format!("trust_url_{}", url),
673	                            question: format!(
674	                                "Trust remote config from {}? (y/N)",
675	                                url
676	                            ),
677	                            prompt_type: PromptType::Confirm,
678	                            default: Some("false".to_string()),
679	                        };
680	
681	                        match ui.prompt(&prompt) {
682	                            Ok(PromptResult::Bool(true)) => {
683	                                trust_store.trust(url);
684	                                store_modified = true;
685	                                Ok(())
686	                            }
687	                            _ => Err(anyhow::anyhow!(
688	                                "Untrusted remote config URL rejected by user: {}",
689	                                url
690	                            )),
691	                        }
692	                    }
693	                }
694	            })
695	            .map_err(BivvyError::Other)?;
696	
697	        if store_modified {
698	            trust_store
699	                .save(trust_store_path)
700	                .map_err(BivvyError::Other)?;
701	        }
702	
703	        Ok(resolved)
704	    } else {
705	        Ok(config)
706	    }
707	}
708	
709	/// Load config with optional path override.
710	///
711	/// If `config_override` is provided, loads only that file without merging.
712	/// Otherwise, discovers and merges all config files.
713	pub fn load_config(project_root: &Path, config_override: Option<&Path>) -> Result<BivvyConfig> {
714	    if let Some(override_path) = config_override {
715	        // Direct load of specified file, no merging
716	        load_config_file(override_path)
717	    } else {
718	        load_merged_config(project_root)
719	    }
720	}
721	
722	/// Load only `.bivvy/config.yml`, with no merging of other files.
723	///
724	/// This is the cheap path used by commands that only operate on the
725	/// project file (like `bivvy add`). It does not consult `~/.bivvy/`,
726	/// split-file directories, or `config.local.yml`. Returns an empty
727	/// `BivvyConfig` when the file does not exist (callers can detect this
728	/// via [`Discovery::project_config_path`] if needed).
729	pub fn load_project_config(project_root: &Path) -> Result<BivvyConfig> {
730	    let discovery = Discovery::new(project_root);
731	    match discovery.project_config_path() {
732	        Some(path) => load_config_file(&path),
733	        None => Err(BivvyError::ConfigNotFound {
734	            path: project_root.join(".bivvy").join("config.yml"),
735	        }),
736	    }
737	}
738	
739	/// Full deep-merge load path, but only the named workflow file
740	/// participates in the chain.
741	///
742	/// This is the loader used by `bivvy run <workflow>`. It walks the
743	/// resolution chain (extends → user-global → project → split steps →
744	/// the named workflow file → local) and produces a final
745	/// [`BivvyConfig`]. Other workflow files are not parsed, so a malformed
746	/// sibling cannot break a run of an unrelated workflow.
747	pub fn load_for_run(project_root: &Path, workflow_name: &str) -> Result<BivvyConfig> {
748	    load_for_run_with_resolver(project_root, workflow_name, &ExtendsResolver::default())
749	}
750	
751	/// Variant of [`load_for_run`] that accepts a custom extends resolver.
752	///
753	/// Exposed for tests that inject a mocked HTTP server.
754	pub fn load_for_run_with_resolver(
755	    project_root: &Path,
756	    workflow_name: &str,
757	    resolver: &ExtendsResolver,
758	) -> Result<BivvyConfig> {
759	    let paths = ConfigPaths::discover(project_root);
760	
761	    if !paths.has_project_config() {
762	        return Err(BivvyError::ConfigNotFound {
763	            path: project_root.join(".bivvy").join("config.yml"),
764	        });
765	    }
766	
767	    let configs = collect_config_values(&paths, WorkflowSelection::One(workflow_name))?;
768	    let merged = merge_configs(&configs);
769	
770	    let mut config: BivvyConfig =
771	        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
772	            path: project_root.join(".bivvy").join("config.yml"),
773	            message: format!("Failed to parse merged config: {}", e),
774	        })?;
775	
776	    config.migrate_deprecated_fields();
777	
778	    if config.extends.is_some() {
779	        let resolved = resolver.resolve(&config)?;
780	        Ok(resolved)
781	    } else {
782	        Ok(config)
783	    }
784	}
785	
786	/// Variant of [`load_for_run`] with trust verification for remote `extends:` URLs.
787	///
788	/// This is the production loader for `bivvy run`. Behavior is identical
789	/// to [`load_merged_config_with_trust`] except that only the named
790	/// workflow file participates in the merge chain.
791	pub fn load_for_run_with_trust(
792	    project_root: &Path,
793	    workflow_name: &str,
