    StepExecutionError { step: String, message: String },

    /// Shell command failed.
    #[error("Command failed with exit code {code:?}: {command}")]
    CommandFailed { command: String, code: Option<i32> },

    /// A required tool or service is missing and cannot be auto-installed.
    #[error("Missing requirement '{requirement}': {message}")]
    RequirementMissing {
        requirement: String,
        message: String,
    },

    /// A requirement check failed unexpectedly (e.g., network error during install).
    #[error("Requirement check failed for '{requirement}': {message}")]
    RequirementCheckFailed {
        requirement: String,
        message: String,
    },

    /// An untrusted remote URL was encountered in non-interactive mode.
    #[error("Untrusted remote config URL: {url}. Use --trust to auto-approve or run interactively to confirm.")]
    UntrustedUrl { url: String },

    /// Shell operation failed (e.g., spawning a debug shell).
    #[error("Shell error: {message}")]
    ShellError { message: String },

    /// Cache subsystem failure (directory creation, metadata I/O).
    #[error("Cache error: {message}")]
    CacheError { message: String },

    /// Session store failure (save, load, cleanup).
    #[error("Session error: {message}")]
    SessionError { message: String },

    /// Feedback store failure (append, read, update).
    #[error("Feedback error: {message}")]
    FeedbackError { message: String },

    /// Remote resource fetch failure (HTTP, git clone, network).
    #[error("Fetch error: {message}")]
    FetchError { message: String },

    /// JSON or YAML serialization/deserialization failure.
    #[error("Serialization error: {message}")]
    SerializationError { message: String },

    /// IO error wrapper.
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),
}

impl From<serde_json::Error> for BivvyError {
    fn from(e: serde_json::Error) -> Self {
        BivvyError::SerializationError {
            message: e.to_string(),
        }
    }
}

impl From<serde_yaml::Error> for BivvyError {
    fn from(e: serde_yaml::Error) -> Self {
        BivvyError::SerializationError {
            message: e.to_string(),
        }
    }
}

impl From<reqwest::Error> for BivvyError {
    fn from(e: reqwest::Error) -> Self {
        BivvyError::FetchError {
            message: e.to_string(),
        }
    }
}

impl From<std::num::ParseIntError> for BivvyError {
    fn from(e: std::num::ParseIntError) -> Self {
        BivvyError::ConfigValidationError {
            message: e.to_string(),
        }
    }
}

/// Result type alias for Bivvy operations.
pub type Result<T> = std::result::Result<T, BivvyError>;

