1	//! Error types for Bivvy operations.
2	//!
3	//! This module defines [`BivvyError`], the primary error type used throughout
4	//! the application, and a [`Result`] type alias for convenience.
5	//!
6	//! Every public module returns [`Result<T>`] so error context is never
7	//! lost at module boundaries.
8	
9	use std::path::PathBuf;
10	use thiserror::Error;
11	
12	/// Core error type for Bivvy operations.
13	#[derive(Debug, Error)]
14	pub enum BivvyError {
15	    /// Configuration file not found at expected location.
16	    #[error("Configuration not found: {path}")]
17	    ConfigNotFound { path: PathBuf },
18	
19	    /// Failed to parse configuration file.
20	    #[error("Failed to parse config at {path}: {message}")]
21	    ConfigParseError { path: PathBuf, message: String },
22	
23	    /// Invalid configuration structure or values.
24	    #[error("Invalid configuration: {message}")]
25	    ConfigValidationError { message: String },
26	
27	    /// Referenced template does not exist.
28	    #[error("Unknown template: {name}")]
29	    UnknownTemplate { name: String },
30	
31	    /// Step dependency cycle detected.
32	    #[error("Circular dependency detected: {cycle}")]
33	    CircularDependency { cycle: String },
34	
35	    /// Step execution failed.
36	    #[error("Step '{step}' failed: {message}")]
37	    StepExecutionError { step: String, message: String },
38	
39	    /// Shell command failed.
40	    #[error("Command failed with exit code {code:?}: {command}")]
41	    CommandFailed { command: String, code: Option<i32> },
42	
43	    /// A required tool or service is missing and cannot be auto-installed.
44	    #[error("Missing requirement '{requirement}': {message}")]
45	    RequirementMissing {
46	        requirement: String,
47	        message: String,
48	    },
49	
50	    /// A requirement check failed unexpectedly (e.g., network error during install).
51	    #[error("Requirement check failed for '{requirement}': {message}")]
52	    RequirementCheckFailed {
53	        requirement: String,
54	        message: String,
55	    },
56	
57	    /// An untrusted remote URL was encountered in non-interactive mode.
58	    #[error("Untrusted remote config URL: {url}. Use --trust to auto-approve or run interactively to confirm.")]
59	    UntrustedUrl { url: String },
60	
61	    /// Shell operation failed (e.g., spawning a debug shell).
62	    #[error("Shell error: {message}")]
63	    ShellError { message: String },
64	
65	    /// Cache subsystem failure (directory creation, metadata I/O).
66	    #[error("Cache error: {message}")]
67	    CacheError { message: String },
68	
69	    /// Session store failure (save, load, cleanup).
70	    #[error("Session error: {message}")]
71	    SessionError { message: String },
72	
73	    /// Feedback store failure (append, read, update).
74	    #[error("Feedback error: {message}")]
75	    FeedbackError { message: String },
76	
77	    /// Remote resource fetch failure (HTTP, git clone, network).
78	    #[error("Fetch error: {message}")]
79	    FetchError { message: String },
80	
81	    /// JSON or YAML serialization/deserialization failure.
82	    #[error("Serialization error: {message}")]
83	    SerializationError { message: String },
84	
85	    /// IO error wrapper.
86	    #[error("IO error: {0}")]
87	    Io(#[from] std::io::Error),
88	}
