176	
177	    #[test]
178	    fn version_constant_exists() {
179	        assert!(!VERSION.is_empty());
180	    }
181	
182	    #[test]
183	    fn is_newer_version_basic() {
184	        assert!(is_newer_version("0.2.0", "0.1.0"));
185	        assert!(is_newer_version("1.0.0", "0.9.0"));
186	        assert!(is_newer_version("0.1.1", "0.1.0"));
187	    }
188	
189	    #[test]
