229	        assert!(!is_newer_version("0.1.0.1", "0.1.0"));
230	    }
231	
232	    #[test]
233	    fn is_newer_version_major_bump() {
234	        assert!(is_newer_version("2.0.0", "1.9.9"));
235	        assert!(is_newer_version("10.0.0", "9.99.99"));
236	    }
237	
238	    #[test]
239	    fn is_newer_version_minor_bump() {
240	        assert!(is_newer_version("1.2.0", "1.1.99"));
241	        assert!(!is_newer_version("1.1.0", "1.2.0"));
242	    }
243	
244	    #[test]
245	    fn is_newer_version_patch_bump() {
246	        assert!(is_newer_version("1.0.5", "1.0.4"));
247	        assert!(!is_newer_version("1.0.4", "1.0.5"));
248	    }
249	
250	    #[test]
251	    fn is_newer_version_with_single_component() {
252	        assert!(is_newer_version("2", "1"));
253	        assert!(!is_newer_version("1", "2"));
254	    }
255	
256	    #[test]
257	    fn is_newer_version_with_two_components() {
258	        assert!(is_newer_version("1.1", "1.0"));
259	        assert!(!is_newer_version("1.0", "1.1"));
260	    }
261	
262	    #[test]
263	    fn clear_cache_works() {
264	        // Clear cache should not panic even if file doesn't exist
265	        let result = clear_cache();
266	        assert!(result.is_ok());
267	    }
268	
269	    #[test]
270	    fn update_info_serialization() {
271	        let info = UpdateInfo {
272	            current: "0.1.0".to_string(),
273	            latest: "0.2.0".to_string(),
274	            update_available: true,
275	            release_url: None,
276	            checked_at: Utc::now(),
277	        };
278	
279	        let json = serde_json::to_string(&info).unwrap();
280	        let parsed: UpdateInfo = serde_json::from_str(&json).unwrap();
281	
282	        assert_eq!(parsed.current, info.current);
283	        assert_eq!(parsed.latest, info.latest);
284	        assert_eq!(parsed.update_available, info.update_available);
285	    }
286	
287	    #[test]
288	    fn update_info_with_no_release_url() {
289	        let info = UpdateInfo {
290	            current: "0.1.0".to_string(),
291	            latest: "0.2.0".to_string(),
292	            update_available: false,
293	            release_url: None,
294	            checked_at: Utc::now(),
295	        };
296	
297	        assert!(!info.update_available);
298	        assert!(info.release_url.is_none());
299	    }
300	
301	    #[test]
302	    fn is_newer_version_empty_string() {
303	        // Edge case: empty strings
304	        // When latest is empty, it has no components, so can't be newer
305	        assert!(!is_newer_version("", "0.1.0"));
306	        // When current is empty, latest has more components, so is "newer"
307	        assert!(is_newer_version("0.1.0", ""));
308	    }
309	
310	    #[test]
311	    fn is_newer_version_invalid_format() {
