30	/// The update command implementation.
31	pub struct UpdateCommand {
32	    args: UpdateArgs,
33	}
34	
35	impl UpdateCommand {
36	    /// Create a new update command.
37	    pub fn new(args: UpdateArgs) -> Self {
38	        Self { args }
39	    }
40	}
41	
42	impl Command for UpdateCommand {
43	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
44	        // Handle auto-update toggle flags
45	        if self.args.enable_auto_update {
46	            return set_auto_update(ui, true);
47	        }
48	        if self.args.disable_auto_update {
49	            return set_auto_update(ui, false);
50	        }
51	
52	        ui.message(&format!("Current version: {}", VERSION));
53	
54	        // Show auto-update status
55	        if is_auto_update_enabled() {
56	            ui.message("Auto-update: enabled");
57	        } else {
58	            ui.message("Auto-update: disabled");
59	        }
60	
61	        ui.message("Checking for updates...");
62	
63	        let info = match check_for_updates_fresh() {
64	            Ok(info) => info,
65	            Err(e) => {
66	                ui.error(&format!("Failed to check for updates: {}", e));
67	                return Ok(CommandResult::failure(1));
68	            }
69	        };
70	
71	        if !info.update_available {
72	            ui.message("You're on the latest version.");
73	            return Ok(CommandResult::success());
74	        }
75	
76	        ui.message(&format!(
77	            "New version available: {} -> {}",
78	            info.current, info.latest
79	        ));
80	
81	        if self.args.check {
82	            if let Some(url) = &info.release_url {
83	                ui.message(&format!("Release: {}", url));
84	            }
85	            return Ok(CommandResult::success());
86	        }
87	
88	        let method = detect_install_method();
89	
90	        if !method.supports_auto_update() {
91	            ui.message(&format!(
92	                "Auto-update is not supported for {} installs.",
93	                method.name()
94	            ));
95	            if let Some(url) = &info.release_url {
96	                ui.message(&format!("Download the latest version from: {}", url));
97	            }
98	            return Ok(CommandResult::success());
99	        }
100	
101	        let update_cmd = method.update_command().unwrap();
102	        ui.message(&format!("Updating via: {}", update_cmd));
103	
104	        let parts: Vec<&str> = update_cmd.split_whitespace().collect();
105	        let status = std::process::Command::new(parts[0])
106	            .args(&parts[1..])
107	            .status()?;
108	
109	        if status.success() {
110	            ui.message("Update complete!");
111	            Ok(CommandResult::success())
112	        } else {
113	            ui.error("Update failed.");
114	            Ok(CommandResult::failure(1))
115	        }
116	    }
117	}
