1	//! HTTP template fetching.
2	//!
3	//! Provides an HTTP client for fetching templates from URLs with
4	//! support for ETag-based conditional requests.
5	
6	use crate::error::{BivvyError, Result};
7	use reqwest::blocking::Client;
8	use std::time::Duration;
9	
10	/// Default maximum response body size (10 MB).
11	const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
12	
13	/// Fetches templates over HTTP/HTTPS.
14	pub struct HttpFetcher {
15	    client: Client,
16	    timeout: Duration,
17	    max_response_size: u64,
18	}
19	
20	/// Response from fetching a template.
21	#[derive(Debug)]
22	pub struct FetchResponse {
23	    /// The template content.
24	    pub content: String,
25	    /// ETag header if present.
26	    pub etag: Option<String>,
27	    /// Last-Modified header if present.
28	    pub last_modified: Option<String>,
29	}
30	
31	impl HttpFetcher {
32	    /// Create a new HTTP fetcher with default 30-second timeout.
33	    pub fn new() -> Self {
34	        Self::with_timeout(Duration::from_secs(30))
35	    }
36	
37	    /// Create a new HTTP fetcher with custom timeout.
38	    pub fn with_timeout(timeout: Duration) -> Self {
39	        Self {
40	            client: Client::builder()
41	                .user_agent("bivvy")
42	                .timeout(timeout)
43	                .build()
44	                .expect("Failed to build HTTP client"),
45	            timeout,
46	            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
47	        }
48	    }
49	
50	    /// Create a new HTTP fetcher with custom timeout and max response size.
51	    #[cfg(test)]
52	    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
53	        Self {
54	            client: Client::builder()
55	                .user_agent("bivvy")
56	                .timeout(timeout)
57	                .build()
58	                .expect("Failed to build HTTP client"),
59	            timeout,
60	            max_response_size,
61	        }
62	    }
63	
64	    /// Get the configured timeout.
65	    pub fn timeout(&self) -> Duration {
66	        self.timeout
67	    }
68	
69	    /// Fetch a template from a URL.
70	    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
71	        let response = self.client.get(url).send()?;
72	
73	        if !response.status().is_success() {
74	            return Err(BivvyError::FetchError { message: format!("HTTP {} fetching {}", response.status(), url) });
75	        }
76	
77	        // Check Content-Length if available
78	        if let Some(len) = response.content_length() {
79	            if len > self.max_response_size {
80	                return Err(BivvyError::FetchError { message: format!(
81	                    "Response too large ({} bytes, max {} bytes) from {}",
82	                    len,
83	                    self.max_response_size,
84	                    url
85	                ) });
86	            }
87	        }
88	
89	        let etag = response
90	            .headers()
91	            .get("etag")
92	            .and_then(|v| v.to_str().ok())
93	            .map(String::from);
94	
95	        let last_modified = response
96	            .headers()
97	            .get("last-modified")
98	            .and_then(|v| v.to_str().ok())
99	            .map(String::from);
100	
101	        let content = response.text()?;
102	
103	        // Also check actual content size (in case Content-Length was missing/wrong)
104	        if content.len() as u64 > self.max_response_size {
105	            return Err(BivvyError::FetchError { message: format!(
106	                "Response too large ({} bytes, max {} bytes) from {}",
107	                content.len(),
108	                self.max_response_size,
109	                url
110	            ) });
111	        }
112	
113	        Ok(FetchResponse {
114	            content,
115	            etag,
116	            last_modified,
117	        })
118	    }
119	
120	    /// Fetch with conditional request (If-None-Match).
121	    ///
122	    /// Returns `None` if content unchanged (304 Not Modified).
123	    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
124	        let mut request = self.client.get(url);
125	
126	        if let Some(etag) = etag {
127	            request = request.header("If-None-Match", etag);
128	        }
129	
130	        let response = request.send()?;
131	
132	        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
133	            return Ok(None);
134	        }
135	
136	        if !response.status().is_success() {
137	            return Err(BivvyError::FetchError { message: format!("HTTP {} fetching {}", response.status(), url) });
138	        }
139	
140	        // Check Content-Length if available
141	        if let Some(len) = response.content_length() {
142	            if len > self.max_response_size {
143	                return Err(BivvyError::FetchError { message: format!(
144	                    "Response too large ({} bytes, max {} bytes) from {}",
145	                    len,
146	                    self.max_response_size,
147	                    url
148	                ) });
149	            }
150	        }
151	
152	        let new_etag = response
153	            .headers()
154	            .get("etag")
155	            .and_then(|v| v.to_str().ok())
156	            .map(String::from);
157	
158	        let last_modified = response
159	            .headers()
160	            .get("last-modified")
161	            .and_then(|v| v.to_str().ok())
162	            .map(String::from);
163	
164	        let content = response.text()?;
165	
166	        // Also check actual content size
167	        if content.len() as u64 > self.max_response_size {
168	            return Err(BivvyError::FetchError { message: format!(
169	                "Response too large ({} bytes, max {} bytes) from {}",
170	                content.len(),
171	                self.max_response_size,
172	                url
173	            ) });
174	        }
175	
176	        Ok(Some(FetchResponse {
177	            content,
178	            etag: new_etag,
179	            last_modified,
180	        }))
181	    }
182	}

1	//! Git template fetching.
2	//!
3	//! Provides functionality for cloning and updating git repositories
4	//! to fetch templates, with support for specific refs and update detection.
5	
6	use crate::error::{BivvyError, Result};
7	use sha2::{Digest, Sha256};
8	use std::path::{Path, PathBuf};
9	
10	/// Allowed URL schemes for git clone operations.
11	///
12	/// Only secure transport protocols are permitted as defense-in-depth:
13	/// - `https://` -- encrypted HTTP transport
14	/// - `ssh://` -- SSH transport
15	/// - `git://` -- native git protocol
16	/// - `git@` -- SCP-style SSH shorthand (e.g. `git@github.com:org/repo.git`)
17	///
18	/// Rejected schemes include `file://` (local filesystem access), `ftp://`,
19	/// and plain `http://` (unencrypted, vulnerable to MITM).
20	pub fn validate_git_url(url: &str) -> Result<()> {
21	    // SCP-style shorthand: git@host:path
22	    if url.starts_with("git@") {
23	        return Ok(());
24	    }
25	
26	    const ALLOWED_SCHEMES: &[&str] = &["https://", "ssh://", "git://"];
27	
28	    for scheme in ALLOWED_SCHEMES {
29	        if url.starts_with(scheme) {
30	            return Ok(());
31	        }
32	    }
33	
34	    return Err(BivvyError::ConfigValidationError { message: format!(
35	        "Unsupported git URL scheme: {url}\n\
36	         Allowed schemes: https://, ssh://, git://, and git@ (SCP-style shorthand)"
37	    ) });
38	}
39	
40	/// Fetches templates from git repositories.
41	pub struct GitFetcher {
42	    /// Directory for cloned repositories.
43	    clone_dir: PathBuf,
44	}
45	
46	/// Information about a git fetch.
47	#[derive(Debug)]
48	pub struct GitFetchResult {
49	    /// Path to the fetched content.
50	    pub local_path: PathBuf,
51	    /// Current commit SHA.
52	    pub commit_sha: String,
53	}
54	
55	impl GitFetcher {
56	    /// Create a new git fetcher.
57	    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
58	        Self {
59	            clone_dir: clone_dir.into(),
60	        }
61	    }
62	
63	    /// Get the clone directory.
64	    pub fn clone_dir(&self) -> &PathBuf {
65	        &self.clone_dir
66	    }
67	
68	    /// Clone or update a repository.
69	    ///
70	    /// Validates the URL scheme before proceeding. Only `https://`, `ssh://`,
71	    /// `git://`, and `git@` SCP-style URLs are allowed.
72	    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
73	        validate_git_url(url)?;
74	        self.fetch_unchecked(url, git_ref)
75	    }
76	
77	    /// Internal fetch without URL validation. Production callers must use
78	    /// [`fetch`](Self::fetch) so the URL scheme is checked first; this is
79	    /// exposed for integration tests that exercise local bare repositories.
80	    pub(crate) fn fetch_unchecked(
81	        &self,
82	        url: &str,
83	        git_ref: Option<&str>,
84	    ) -> Result<GitFetchResult> {
85	        let repo_path = self.repo_path(url);
86	
87	        if repo_path.exists() {
88	            self.update_repo(&repo_path, git_ref)?;
89	        } else {
90	            self.clone_repo(url, &repo_path, git_ref)?;
91	        }
92	
93	        let commit_sha = self.get_head_sha(&repo_path)?;
94	
95	        Ok(GitFetchResult {
96	            local_path: repo_path,
97	            commit_sha,
98	        })
99	    }
100	
101	    /// Check if a repository has new commits.
102	    ///
103	    /// Validates the URL scheme before proceeding.
104	    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
105	        validate_git_url(url)?;
106	        self.has_updates_unchecked(url, git_ref, current_sha)
107	    }
108	
109	    /// Internal has_updates without URL validation.
110	    fn has_updates_unchecked(
111	        &self,
112	        url: &str,
113	        git_ref: Option<&str>,
114	        current_sha: &str,
115	    ) -> Result<bool> {
116	        let remote_sha = self.resolve_ref_unchecked(url, git_ref)?;
117	        Ok(remote_sha != current_sha)
118	    }
119	
120	    /// Get the current commit SHA for a ref using ls-remote.
121	    ///
122	    /// Validates the URL scheme before proceeding.
123	    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
124	        validate_git_url(url)?;
125	        self.resolve_ref_unchecked(url, git_ref)
126	    }
127	
128	    /// Internal resolve_ref without URL validation.
129	    fn resolve_ref_unchecked(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
130	        let refspec = git_ref.unwrap_or("HEAD");
131	
132	        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
133	        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
134	        let candidates = if refspec == "HEAD" {
135	            vec![refspec.to_string()]
136	        } else {
137	            vec![
138	                refspec.to_string(),
139	                format!("refs/heads/{refspec}"),
140	                format!("refs/tags/{refspec}"),
141	            ]
142	        };
143	
144	        for candidate in &candidates {
145	            let output = std::process::Command::new("git")
146	                .args(["ls-remote", url, candidate])
147	                .output()?;
148	
149	            if !output.status.success() {
150	                return Err(BivvyError::FetchError { message: format!(
151	                    "Failed to query remote: {}",
152	                    String::from_utf8_lossy(&output.stderr)
153	                ) });
154	            }
155	
156	            let stdout = String::from_utf8_lossy(&output.stdout);
157	            if let Some(sha) = stdout
158	                .lines()
159	                .next()
160	                .and_then(|line| line.split_whitespace().next())
161	            {
162	                return Ok(sha.to_string());
163	            }
164	        }
165	
166	        return Err(BivvyError::FetchError { message: format!("Could not resolve ref '{refspec}' from {url}") })
167	    }
168	
