1	//! Configuration inheritance resolution.
2	//!
3	//! This module handles the `extends:` configuration feature, which allows
4	//! configs to inherit from remote base configurations.
5	
6	use std::collections::HashSet;
7	use std::time::Duration;
8	
9	use crate::error::{BivvyError, Result};
10	
11	use super::merger::deep_merge_with_leaves;
12	use super::remote::RemoteFetcher;
13	use super::schema::{BivvyConfig, ExtendsConfig};
14	
15	/// Resolves configuration inheritance chain.
16	///
17	/// # Example
18	///
19	/// ```no_run
20	/// use bivvy::config::{BivvyConfig, ExtendsResolver};
21	///
22	/// let resolver = ExtendsResolver::new();
23	///
24	/// // Resolve a config that extends a remote base
25	/// let config: BivvyConfig = serde_yaml::from_str(r#"
26	/// extends:
27	///   - url: https://example.com/base-config.yml
28	/// app_name: MyApp
29	/// "#).unwrap();
30	///
31	/// let resolved = resolver.resolve(&config).unwrap();
32	/// ```
33	pub struct ExtendsResolver {
34	    fetcher: RemoteFetcher,
35	    max_depth: usize,
36	}
37	
38	impl ExtendsResolver {
39	    /// Create a resolver with default settings.
40	    pub fn new() -> Self {
41	        Self {
42	            fetcher: RemoteFetcher::new(Duration::from_secs(30)),
43	            max_depth: 10,
44	        }
45	    }
46	
47	    /// Create a resolver with a custom fetcher.
48	    pub fn with_fetcher(fetcher: RemoteFetcher) -> Self {
49	        Self {
50	            fetcher,
51	            max_depth: 10,
52	        }
53	    }
54	
55	    /// Create a resolver with custom max depth.
56	    pub fn with_max_depth(max_depth: usize) -> Self {
57	        Self {
58	            fetcher: RemoteFetcher::default(),
59	            max_depth,
60	        }
61	    }
62	
63	    /// Resolve all extends references and merge configs.
64	    pub fn resolve(&self, config: &BivvyConfig) -> Result<BivvyConfig> {
65	        self.resolve_with_visited(config, &mut HashSet::new(), 0, &mut |_| Ok(()))
66	    }
67	
68	    /// Resolve extends with a trust checker.
69	    ///
70	    /// The `trust_check` closure is called for each URL before it is fetched.
71	    /// It should return `Ok(())` if the URL is trusted, or an error to abort.
72	    /// This enables the caller to prompt the user, check a trust store, or
73	    /// reject untrusted URLs based on the current trust policy.
74	    pub fn resolve_with_trust<F>(
75	        &self,
76	        config: &BivvyConfig,
77	        trust_check: &mut F,
78	    ) -> Result<BivvyConfig>
79	    where
80	        F: FnMut(&str) -> Result<()>,
81	    {
82	        self.resolve_with_visited(config, &mut HashSet::new(), 0, trust_check)
83	    }
84	
85	    fn resolve_with_visited<F>(
86	        &self,
87	        config: &BivvyConfig,
88	        visited: &mut HashSet<String>,
89	        depth: usize,
90	        trust_check: &mut F,
91	    ) -> Result<BivvyConfig>
92	    where
93	        F: FnMut(&str) -> Result<()>,
94	    {
95	        if depth > self.max_depth {
96	            return Err(BivvyError::ConfigValidationError {
97	                message: format!(
98	                    "Config extends depth exceeds maximum of {}",
99	                    self.max_depth
100	                ),
101	            });
102	        }
103	
104	        // If no extends, return config as-is
105	        let extends = match &config.extends {
106	            Some(e) if !e.is_empty() => e,
107	            _ => return Ok(config.clone()),
108	        };
109	
110	        // Convert current config to Value for merging
111	        let config_value = serde_yaml::to_value(config)?;
112	
113	        // Environment override blocks should replace entirely, not field-merge
114	        let leaf_keys = std::collections::HashSet::from(["environments"]);
115	
116	        // Start with empty Value
117	        let mut merged = serde_yaml::Value::Mapping(serde_yaml::Mapping::new());
118	
119	        // Process each base config in order
120	        for ext in extends {
121	            // Check for cycles
122	            if visited.contains(&ext.url) {
123	                return Err(BivvyError::ConfigValidationError {
124	                    message: format!("Circular extends detected: {}", ext.url),
125	                });
126	            }
127	            visited.insert(ext.url.clone());
128	
129	            // Check trust before fetching
130	            trust_check(&ext.url)?;
131	
132	            // Fetch and parse base config
133	            let content = self.fetcher.fetch(&ext.url)?;
134	            let base_config: BivvyConfig = serde_yaml::from_str(&content)?;
135	
136	            // Recursively resolve base's extends
137	            let resolved_base =
138	                self.resolve_with_visited(&base_config, visited, depth + 1, trust_check)?;
139	
140	            // Convert to Value and merge
141	            let base_value = serde_yaml::to_value(&resolved_base)?;
142	            merged = deep_merge_with_leaves(&merged, &base_value, &leaf_keys);
143	        }
144	
145	        // Finally merge the current config on top
146	        let final_value = deep_merge_with_leaves(&merged, &config_value, &leaf_keys);
147	
148	        // Deserialize back to BivvyConfig
149	        let mut final_config: BivvyConfig = serde_yaml::from_value(final_value)?;
150	
151	        // Clear extends from final config (already resolved)
152	        final_config.extends = None;
153	
154	        Ok(final_config)
155	    }

