            "session": "sess_test",
            "type": "workflow_completed",
            "name": "default",
            "success": true,
            "aborted": false,
            "steps_run": 3,
            "steps_skipped": 1,
            "duration_ms": 5000
        });
        std::fs::write(&log_file, format!("{}\n", event_line)).unwrap();

        // scan_log_files uses default_log_dir() which won't find our temp dir,
        // so we test the parsing logic directly
        let content = std::fs::read_to_string(&log_file).unwrap();
        let value: serde_json::Value = serde_json::from_str(content.trim()).unwrap();
        assert_eq!(value["type"], "workflow_completed");
        assert_eq!(value["name"], "default");
        assert_eq!(value["success"], true);
        assert_eq!(value["steps_run"], 3);
    }

    #[test]
    fn log_run_record_serializes_to_json() {
        let record = LogRunRecord {
            timestamp: chrono::Utc::now(),
            workflow: "default".to_string(),
            success: true,
            aborted: false,
            steps_run: 3,
            steps_skipped: 1,
            duration_ms: 5000,
            log_file: Some("test.jsonl".to_string()),
        };

        let json = serde_json::to_string(&record).unwrap();
        let value: serde_json::Value = serde_json::from_str(&json).unwrap();
        assert_eq!(value["workflow"], "default");
        assert_eq!(value["success"], true);
        // log_file should be skipped in serialization
        assert!(value.get("log_file").is_none());
    }

    /// Helper: write a log file with `session_started` + `workflow_completed`.
    fn write_run_log(log_dir: &Path, name: &str, project: &Path, workflow: &str) {
        let session_started = serde_json::json!({
            "ts": "2026-04-25T10:00:00.000Z",
            "session": "sess_test",
            "type": "session_started",
            "command": "run",
            "args": [workflow],
            "version": "1.9.0",
            "working_directory": project.display().to_string()
        });
        let workflow_completed = serde_json::json!({
            "ts": "2026-04-25T10:00:02.000Z",
            "session": "sess_test",
            "type": "workflow_completed",
            "name": workflow,
            "success": true,
            "aborted": false,
            "steps_run": 1,
            "steps_skipped": 0,
            "duration_ms": 1000
        });
        std::fs::write(
            log_dir.join(name),
            format!("{}\n{}\n", session_started, workflow_completed),
        )
        .unwrap();
    }

    #[test]
    fn scan_log_dir_filters_other_projects() {
        let project_a = TempDir::new().unwrap();
        let project_b = TempDir::new().unwrap();
        let canonical_a = project_a.path().canonicalize().unwrap();
        let canonical_b = project_b.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-03_aaaa.jsonl",
            &canonical_a,
            "default",
        );
        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-04_bbbb.jsonl",
            &canonical_b,
            "default",
        );
        write_run_log(
            log_dir.path(),
            "2026-04-28T22-26-05_cccc.jsonl",
            &canonical_a,
            "quick",
        );

        let records_a = scan_log_dir(log_dir.path(), 100, &canonical_a);
        assert_eq!(records_a.len(), 2);
        let workflows: Vec<&str> = records_a.iter().map(|r| r.workflow.as_str()).collect();
        assert!(workflows.contains(&"default"));
        assert!(workflows.contains(&"quick"));

        let records_b = scan_log_dir(log_dir.path(), 100, &canonical_b);
        assert_eq!(records_b.len(), 1);
    }

    #[test]
    fn scan_log_dir_respects_limit() {
        let project = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        for i in 0..5 {
            write_run_log(
                log_dir.path(),
                &format!("2026-04-28T22-26-0{}_aaaa.jsonl", i),
                &canonical,
                "default",
            );
        }

        let records = scan_log_dir(log_dir.path(), 3, &canonical);
        assert_eq!(records.len(), 3);
    }

    /// Helper: write a session_started + workflow_completed pair into a log
    /// file owned by `project`. Mirrors the real bivvy log shape.
    fn write_clear_log(log_dir: &Path, name: &str, project: &Path) {
        let session_started = serde_json::json!({
            "ts": "2026-04-25T10:00:00.000Z",
            "session": "sess_clear",
            "type": "session_started",
            "command": "run",
            "args": ["default"],
            "version": "1.9.0",
            "working_directory": project.display().to_string()
        });
        std::fs::write(log_dir.join(name), format!("{}\n", session_started)).unwrap();
    }

    #[test]
    fn clear_reports_when_no_logs_match() {
        let project = TempDir::new().unwrap();
        let logs = TempDir::new().unwrap();

        let other = TempDir::new().unwrap();
        write_clear_log(
            logs.path(),
            "other.jsonl",
            &other.path().canonicalize().unwrap(),
        );

        let cmd = HistoryCommand::new(
            project.path(),
            HistoryArgs {
                clear: true,
                force: true,
                ..Default::default()
            },
        );
        let mut ui = MockUI::new();

        let result = cmd.clear_history_in(logs.path(), &mut ui).unwrap();
        assert!(result.success);
        assert!(ui.has_message("No run history to clear for this project."));
        // The other project's log must remain on disk.
        assert!(logs.path().join("other.jsonl").exists());
    }

    #[test]
    fn clear_with_force_deletes_only_this_projects_logs() {
        let project = TempDir::new().unwrap();
        let other = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let canonical_other = other.path().canonicalize().unwrap();
        let logs = TempDir::new().unwrap();

        write_clear_log(logs.path(), "mine_a.jsonl", &canonical);
        write_clear_log(logs.path(), "mine_b.jsonl", &canonical);
        write_clear_log(logs.path(), "theirs.jsonl", &canonical_other);

        let cmd = HistoryCommand::new(
            project.path(),
            HistoryArgs {
                clear: true,
                force: true,
                ..Default::default()
            },
        );
        let mut ui = MockUI::new();

        let result = cmd.clear_history_in(logs.path(), &mut ui).unwrap();
        assert!(result.success);
        assert!(ui.has_success("Cleared 2 run logs for this project"));

        assert!(!logs.path().join("mine_a.jsonl").exists());
        assert!(!logs.path().join("mine_b.jsonl").exists());
        assert!(logs.path().join("theirs.jsonl").exists());
        // No interactive prompt should fire when --force is set.
        assert!(ui.prompts_shown().is_empty());
    }

    #[test]
    fn clear_prompts_when_interactive_without_force() {
        let project = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let logs = TempDir::new().unwrap();

        write_clear_log(logs.path(), "mine.jsonl", &canonical);

        let cmd = HistoryCommand::new(
            project.path(),
            HistoryArgs {
                clear: true,
                force: false,
                ..Default::default()
            },
        );
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("clear_history", "true");

        let result = cmd.clear_history_in(logs.path(), &mut ui).unwrap();
        assert!(result.success);
        assert!(ui.prompts_shown().iter().any(|k| k == "clear_history"));
        assert!(ui.has_success("Cleared 1 run log for this project"));
        assert!(!logs.path().join("mine.jsonl").exists());
    }

    #[test]
    fn clear_cancelled_when_user_declines_prompt() {
        let project = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let logs = TempDir::new().unwrap();

        write_clear_log(logs.path(), "mine.jsonl", &canonical);

        let cmd = HistoryCommand::new(
            project.path(),
            HistoryArgs {
                clear: true,
                force: false,
                ..Default::default()
            },
        );
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("clear_history", "false");

        let result = cmd.clear_history_in(logs.path(), &mut ui).unwrap();
        assert!(result.success);
        assert!(ui.has_message("Cancelled"));
        // The log must still be on disk.
        assert!(logs.path().join("mine.jsonl").exists());
    }

    #[test]
    fn scan_log_dir_skips_logs_without_working_directory() {
        let project = TempDir::new().unwrap();
        let canonical = project.path().canonicalize().unwrap();
        let log_dir = TempDir::new().unwrap();

        // Log without working_directory — must be excluded under project scoping.
        let event_line = serde_json::json!({
            "ts": "2026-04-25T10:00:00.000Z",
            "session": "sess_old",
            "type": "workflow_completed",
            "name": "default",
            "success": true,
            "aborted": false,
            "steps_run": 1,
            "steps_skipped": 0,
            "duration_ms": 1000
        });
        std::fs::write(
            log_dir.path().join("2026-04-28T22-26-00_old.jsonl"),
            format!("{}\n", event_line),
        )
        .unwrap();

        let records = scan_log_dir(log_dir.path(), 100, &canonical);
        assert!(records.is_empty());
    }
}

