//! Automatic fix application.
//!
//! This module provides functionality for automatically fixing
//! configuration issues detected by lint rules.

use crate::lint::LintDiagnostic;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// A code fix that can be applied automatically.
#[derive(Debug, Clone)]
pub struct Fix {
    /// File to modify.
    pub file: PathBuf,
    /// Start byte offset.
    pub start: usize,
    /// End byte offset.
    pub end: usize,
    /// Replacement text.
    pub replacement: String,
}

/// Result of attempting to apply fixes.
#[derive(Debug)]
pub struct FixResult {
    /// Number of fixes applied.
    pub applied: usize,
    /// Diagnostics that couldn't be auto-fixed.
    pub unfixable: Vec<LintDiagnostic>,
    /// Errors that occurred during fixing.
    pub errors: Vec<String>,
}

/// Engine for applying automatic fixes.
pub struct FixEngine;

impl FixEngine {
    /// Create a new fix engine.
    pub fn new() -> Self {
        Self
    }

    /// Apply fixes from diagnostics that support auto-fix.
    pub fn apply_fixes(&self, diagnostics: &[LintDiagnostic], fixes: &[Fix]) -> FixResult {
        let mut applied = 0;
        let mut errors = Vec::new();

        // Group fixes by file
        let mut fixes_by_file: HashMap<&Path, Vec<&Fix>> = HashMap::new();
        for fix in fixes {
            fixes_by_file
                .entry(fix.file.as_path())
                .or_default()
                .push(fix);
        }

        // Apply fixes to each file
        for (file, file_fixes) in fixes_by_file {
            match self.apply_fixes_to_file(file, &file_fixes) {
                Ok(count) => applied += count,
                Err(e) => errors.push(format!("{}: {}", file.display(), e)),
            }
        }

        // Collect unfixable diagnostics
        let unfixable = diagnostics
            .iter()
            .filter(|d| d.suggestion.is_none())
            .cloned()
            .collect();

        FixResult {
            applied,
            unfixable,
            errors,
        }
    }

    /// Preview fixes without applying them.
    pub fn preview_fixes(&self, fixes: &[Fix]) -> Vec<String> {
        fixes
            .iter()
            .map(|f| {
                format!(
                    "{}:{}-{}: Replace with '{}'",
                    f.file.display(),
                    f.start,
                    f.end,
                    f.replacement
                )
            })
            .collect()
    }

    fn apply_fixes_to_file(&self, file: &Path, fixes: &[&Fix]) -> Result<usize, String> {
        let content =
            fs::read_to_string(file).map_err(|e| format!("Failed to read file: {}", e))?;

        // Sort fixes by start position (reverse order for safe replacement)
        let mut sorted_fixes = fixes.to_vec();
        sorted_fixes.sort_by(|a, b| b.start.cmp(&a.start));

        let mut new_content = content;
        for fix in &sorted_fixes {
            if fix.start <= new_content.len() && fix.end <= new_content.len() {
                new_content = format!(
                    "{}{}{}",
                    &new_content[..fix.start],
                    &fix.replacement,
                    &new_content[fix.end..]
                );
            }
        }

        fs::write(file, new_content).map_err(|e| format!("Failed to write file: {}", e))?;

        Ok(sorted_fixes.len())
    }
}

impl Default for FixEngine {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn applies_simple_fix() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.yml");
        fs::write(&config_path, "app_name: \"My App\"\n").unwrap();

        let fix = Fix {
            file: config_path.clone(),
            start: 10,
            end: 18,
            replacement: "\"my-app\"".to_string(),
        };

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&[], &[fix]);

        assert_eq!(result.applied, 1);

        let content = fs::read_to_string(&config_path).unwrap();
        assert!(content.contains("my-app"));
    }

    #[test]
    fn applies_multiple_fixes_to_same_file() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.yml");
        fs::write(&config_path, "aaa bbb ccc").unwrap();

        let fixes = vec![
            Fix {
                file: config_path.clone(),
                start: 0,
                end: 3,
                replacement: "AAA".to_string(),
            },
            Fix {
                file: config_path.clone(),
                start: 8,
                end: 11,
                replacement: "CCC".to_string(),
            },
        ];

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&[], &fixes);

        assert_eq!(result.applied, 2);

        let content = fs::read_to_string(&config_path).unwrap();
        assert_eq!(content, "AAA bbb CCC");
    }

    #[test]
    fn reports_unfixable_diagnostics() {
        use crate::lint::{RuleId, Severity};

        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Cannot auto-fix circular dependencies",
        )];

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&diagnostics, &[]);

        assert_eq!(result.applied, 0);
        assert_eq!(result.unfixable.len(), 1);
    }

    #[test]
    fn preview_fixes_returns_descriptions() {
        let fix = Fix {
            file: PathBuf::from("config.yml"),
            start: 10,
            end: 20,
            replacement: "new_value".to_string(),
        };

        let engine = FixEngine::new();
        let previews = engine.preview_fixes(&[fix]);

        assert_eq!(previews.len(), 1);
        assert!(previews[0].contains("config.yml:10-20"));
        assert!(previews[0].contains("new_value"));
    }

    #[test]
    fn handles_file_not_found() {
        let fix = Fix {
            file: PathBuf::from("/nonexistent/path/config.yml"),
            start: 0,
            end: 5,
            replacement: "test".to_string(),
        };

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&[], &[fix]);

        assert_eq!(result.applied, 0);
        assert_eq!(result.errors.len(), 1);
    }
}

//! Workflow-level display contract.
//!
//! Owns the run header, persistent progress bar (pinned at the bottom),
//! and the run summary. Delegates per-step rendering to
//! [`super::StepDisplay`].
//!
//! ## Construction
//!
//! - Interactive runs: [`TerminalWorkflowDisplay::new`] with an
//!   [`Arc<TerminalSurface>`] and [`OutputMode`].
//! - CI / non-interactive: [`NonInteractiveWorkflowDisplay::new`].

use std::sync::Arc;
use std::time::Duration;

use indicatif::{ProgressBar, ProgressStyle};

use crate::ui::progress::format_duration;
use crate::ui::surface::{PinnedBar, TerminalSurface};
use crate::ui::theme::BivvyTheme;
use crate::ui::OutputMode;

use super::step::{NonInteractiveStepDisplay, StepDisplay, TerminalStepDisplay};
use super::{RunHeader, RunSummary};

/// Workflow-level display contract.
///
/// Implementations own the workflow's pinned progress bar (if any) and
/// produce per-step displays via [`Self::begin_step`].
pub trait WorkflowDisplay {
    /// Show the rich run header at the top of a run.
    fn show_run_header(&mut self, hdr: &RunHeader);

    /// Initialize the persistent progress bar.
    ///
    /// Called once before the step loop. Implementations that don't
    /// support a pinned bar (CI mode, silent mode) make this a no-op.
    fn start_progress(&mut self, total: usize);

    /// Update the progress bar.
    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration);

    /// Finish and clear the progress bar before the summary is rendered.
    fn finish_progress(&mut self);

    /// Show a run summary at the end of a run.
    fn show_run_summary(&mut self, summary: &RunSummary);

    /// Hand off to the step layer.
    ///
    /// The returned [`StepDisplay`] shares only the surface (or output
    /// stream) with the workflow — never any draw state.
    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay>;

    /// Print a status line above the pinned region (used for filter
    /// reasons, dry-run notes, etc.).
    fn message(&mut self, msg: &str);

    /// Print a hint (post-run guidance) above the pinned region.
    fn hint(&mut self, hint: &str);
}

// ────────────────────────── Interactive impl ──────────────────────────

/// Interactive workflow display backed by a [`TerminalSurface`].
pub struct TerminalWorkflowDisplay {
    surface: Arc<TerminalSurface>,
    theme: BivvyTheme,
    mode: OutputMode,
    pinned: Option<PinnedBar>,
}

impl TerminalWorkflowDisplay {
    /// Construct a new terminal workflow display.
    pub fn new(surface: Arc<TerminalSurface>, mode: OutputMode) -> Self {
        let theme = if crate::ui::should_use_colors() {
            BivvyTheme::new()
        } else {
            BivvyTheme::plain()
        };
        Self {
            surface,
            theme,
            mode,
            pinned: None,
        }
    }

    /// Format the bar message string with bracket bar + counts.
    fn format_bar(theme: &BivvyTheme, current: usize, total: usize, elapsed: Duration) -> String {
        let filled = if total > 0 { (current * 16) / total } else { 0 };
        let empty = 16usize.saturating_sub(filled);
        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
        format!(
            "\n{} {}/{} steps {} {}",
            theme.info.apply_to(format!("[{}]", bar)),
            current,
            total,
            theme.dim.apply_to("·"),
            theme
                .duration
                .apply_to(format!("{} elapsed", format_duration(elapsed))),
        )
    }
}

impl WorkflowDisplay for TerminalWorkflowDisplay {
    fn show_run_header(&mut self, hdr: &RunHeader) {
        if !self.mode.shows_status() {
            return;
        }
        let step_label = if hdr.step_count == 1 { "step" } else { "steps" };
        self.surface.println(&format!(
            "\n{} {} {} {} {} {} {}\n",
            self.theme.header.apply_to("⛺"),
            self.theme.highlight.apply_to(&hdr.app_name),
            self.theme.dim.apply_to(format!("v{}", hdr.version)),
            self.theme.dim.apply_to("·"),
            self.theme
                .dim
                .apply_to(format!("{} workflow", hdr.workflow)),
            self.theme
                .dim
                .apply_to(format!("· {} {}", hdr.step_count, step_label)),
            self.theme.dim.apply_to(format!("· env: {}", hdr.env_name)),
        ));
    }

    fn start_progress(&mut self, total: usize) {
        if !self.mode.shows_status() {
            return;
        }
        let bar = ProgressBar::new(total as u64);
        bar.set_style(ProgressStyle::default_bar().template("{msg}").unwrap());
        bar.set_message(Self::format_bar(&self.theme, 0, total, Duration::ZERO));
        self.pinned = Some(self.surface.pin_bottom(bar));
    }

    fn update_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
        if !self.mode.shows_status() {
            return;
        }
        if let Some(p) = &self.pinned {
            p.set_message(Self::format_bar(&self.theme, current, total, elapsed));
        }
    }

    fn finish_progress(&mut self) {
        // Drop clears the bar.
        self.pinned = None;
    }

    fn show_run_summary(&mut self, summary: &RunSummary) {
        if !self.mode.shows_status() {
            return;
        }

        let b = &self.theme.border;
        let mut lines = vec![
            String::new(),
            format!(
                "{} {}",
                b.apply_to("┌─"),
                b.apply_to("Summary ──────────────────────────")
            ),
        ];

        for step in &summary.step_results {
            let icon = step.status.styled(&self.theme);
            let duration_str = step.duration.map(format_duration).unwrap_or_default();
            let detail_str = step.detail.as_deref().unwrap_or("");

            let right_side = if !duration_str.is_empty() {
                self.theme.duration.apply_to(duration_str).to_string()
            } else if !detail_str.is_empty() {
                self.theme.dim.apply_to(detail_str).to_string()
            } else {
                String::new()
            };

            lines.push(format!(
                "{} {} {:<20} {}",
                b.apply_to("│"),
                icon,
                step.name,
                right_side,
            ));
        }

        let satisfied_part = if summary.steps_satisfied > 0 {
            format!(
                " {} {} already satisfied",
                self.theme.dim.apply_to("·"),
                summary.steps_satisfied,
            )
        } else {
            String::new()
        };
        lines.push(
            b.apply_to("├────────────────────────────────────")
                .to_string(),
        );
        lines.push(format!(
            "{} Total: {} {} {} run {} {} skipped{}",
            b.apply_to("│"),
            self.theme
                .duration
                .apply_to(format_duration(summary.total_duration)),
            self.theme.dim.apply_to("·"),
            summary.steps_run,
            self.theme.dim.apply_to("·"),
            summary.steps_skipped,
            satisfied_part,
        ));
        lines.push(
            b.apply_to("└────────────────────────────────────")
                .to_string(),
        );

        for line in &lines {
            self.surface.println(line);
        }
    }

    fn begin_step(&mut self, index: usize, total: usize) -> Box<dyn StepDisplay> {
        Box::new(TerminalStepDisplay::new(
            Arc::clone(&self.surface),
            self.mode,
            index,
            total,
        ))
    }

    fn message(&mut self, msg: &str) {
        if self.mode.shows_status() {
            self.surface.println(msg);
        }
    }

    fn hint(&mut self, hint: &str) {
        if !self.mode.shows_status() {
            return;
        }
        self.surface
            .println(&self.theme.hint.apply_to(hint).to_string());
        self.surface.println("");
    }
}

